<script setup lang="ts">defineProps<{locale:'zh'|'en'}>();const agent=ref('*');const disallow=ref('/private/');const allow=ref('');const result=computed(()=>`User-agent: ${agent.value.trim()||'*'}\n${disallow.value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>`Disallow: ${x}`).join('\n')}${allow.value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>`\nAllow: ${x}`).join('')}\n`);const {copied,copy}=useCopy()</script><template><div class="tool-form"><label>User-agent<input v-model="agent" placeholder="*"></label><label>Disallow <small>{{locale==='zh'?'每行一条路径':'One path per line'}}</small><textarea v-model="disallow" rows="3" /></label><label>Allow <small>{{locale==='zh'?'每行一条路径':'One path per line'}}</small><textarea v-model="allow" rows="2" /></label><div class="result-header"><span>ROBOTS.TXT</span><button type="button" @click="copy(result)">{{copied?(locale==='zh'?'已复制':'Copied'):(locale==='zh'?'复制结果':'Copy result')}}</button></div><pre class="code-result">{{result}}</pre></div></template>